#include <iostream>
#include <array>

const long long MOD = 1000000007LL;

struct TransitionMatrix {
    std::array<std::array<long long, 4>, 4> m;

    TransitionMatrix() {
        for (int i = 0; i < 4; ++i) {
            for (int j = 0; j < 4; ++j) {
                m[i][j] = 0;
            }
        }
    }

    long long operator()(int i, int j) const {
        return m[i][j];
    }

    long long& operator()(int i, int j) {
        return m[i][j];
    }

    TransitionMatrix operator*(const TransitionMatrix& other) const {
        TransitionMatrix result;
        for (int i = 0; i < 4; ++i) {
            for (int j = 0; j < 4; ++j) {
                long long x = 0;
                for (int k = 0; k < 4; ++k) {
                    x = (x + (m[i][k] * other.m[k][j])) % MOD;
                }
                result.m[i][j] = x;
            }
        }
        return result;
    }
};

TransitionMatrix identity_matrix() {
    TransitionMatrix result;
    result(0,0) = 1;
    result(1,1) = 1;
    result(2,2) = 1;
    result(3,3) = 1;
    return result;
}

TransitionMatrix ant_matrix() {
    TransitionMatrix result;
    for (int i = 0; i < 4; ++i) {
        for (int j = 0; j < 4; ++j) {
            result(i,j) = 1;
        }
    }
    result(0,0) = 0;
    result(1,1) = 0;
    result(2,2) = 0;
    result(3,3) = 0;
    return result;
}

TransitionMatrix raise_to(TransitionMatrix t, int x) {
    if (x == 0) {
        return identity_matrix();
    } else if (x % 2 == 0) {
        TransitionMatrix t_sqr = t * t;
        return raise_to(t_sqr, x / 2);
    } else {
        TransitionMatrix t_sqr = t * t;
        return t * raise_to(t_sqr, (x - 1) / 2);
    }
}

long long num_paths(int n) {
    TransitionMatrix t_matrix = ant_matrix();
    TransitionMatrix result = raise_to(t_matrix, n);
    return result(0, 0);
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    if (std::cin >> n) {
        std::cout << num_paths(n) << std::endl;
    }
    return 0;
}

